import { test, expect } from '@playwright/test';

test.describe('Search Filter Results Count', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com/search');
    await page.waitForLoadState('networkidle');
  });

  test('should display result count for category filter options', async ({ page }) => {
    // Expand the category filter section
    const categoryFilterButton = page.getByRole('button', { name: /category/i });
    await categoryFilterButton.click();

    // Verify that each category option shows a result count
    const categoryOptions = page.getByRole('checkbox').filter({ hasText: /\(\d+\)/ });
    const count = await categoryOptions.count();
    expect(count).toBeGreaterThan(0);

    // Verify specific category option displays count in format like "Electronics (45)"
    const electronicsOption = page.getByLabel(/electronics/i);
    const electronicsText = await electronicsOption.textContent();
    expect(electronicsText).toMatch(/\(\d+\)/);
  });

  test('should display result count for price range filter options', async ({ page }) => {
    // Expand the price filter section
    const priceFilterButton = page.getByRole('button', { name: /price/i });
    await priceFilterButton.click();

    // Verify that each price range option shows a result count
    const priceOptions = page.getByRole('radio').filter({ hasText: /\(\d+\)/ });
    const count = await priceOptions.count();
    expect(count).toBeGreaterThan(0);

    // Verify specific price range displays count
    const underFiftyOption = page.getByLabel(/under \$50/i);
    const underFiftyText = await underFiftyOption.textContent();
    expect(underFiftyText).toMatch(/\(\d+\)/);
  });

  test('should update result counts when applying filters', async ({ page }) => {
    // Get initial count for a filter option
    const categoryFilterButton = page.getByRole('button', { name: /category/i });
    await categoryFilterButton.click();

    const electronicsOption = page.getByLabel(/electronics/i);
    const initialText = await electronicsOption.textContent();
    const initialCount = initialText?.match(/\((\d+)\)/)?.[1];

    // Apply a different filter
    const priceFilterButton = page.getByRole('button', { name: /price/i });
    await priceFilterButton.click();
    const underFiftyOption = page.getByLabel(/under \$50/i);
    await underFiftyOption.click();

    // Wait for results to update
    await page.waitForLoadState('networkidle');

    // Verify that the electronics count has been updated
    const updatedText = await electronicsOption.textContent();
    const updatedCount = updatedText?.match(/\((\d+)\)/)?.[1];

    expect(updatedCount).toBeDefined();
    // The count may change after applying a filter
    expect(updatedText).toMatch(/\(\d+\)/);
  });

  test('should display zero count for unavailable filter options', async ({ page }) => {
    // Apply a restrictive filter first
    const categoryFilterButton = page.getByRole('button', { name: /category/i });
    await categoryFilterButton.click();

    const electronicsOption = page.getByLabel(/electronics/i);
    await electronicsOption.click();

    await page.waitForLoadState('networkidle');

    // Expand another filter to see which options have zero results
    const brandFilterButton = page.getByRole('button', { name: /brand/i });
    await brandFilterButton.click();

    // Verify that options with zero results are displayed with (0)
    const brandOptions = page.getByRole('checkbox').filter({ hasText: /\(0\)/ });
    const zeroCountOptions = await brandOptions.count();

    // There should be at least some options, and some may have zero results
    const allBrandOptions = page.getByRole('checkbox');
    const totalOptions = await allBrandOptions.count();
    expect(totalOptions).toBeGreaterThan(0);
  });

  test('should display result counts in correct format for all filter types', async ({ page }) => {
    // Get all filter sections
    const filterButtons = page.getByRole('button').filter({ hasText: /filter|sort/i });
    const filterCount = await filterButtons.count();

    // Expand each filter section and verify count format
    for (let i = 0; i < Math.min(filterCount, 3); i++) {
      const buttons = page.getByRole('button').filter({ hasText: /filter|sort/i });
      const button = buttons.nth(i);
      await button.click();
      await page.waitForLoadState('networkidle');

      // Verify all options in this filter show counts
      const options = page.getByRole('checkbox', { checked: false }).or(page.getByRole('checkbox', { checked: true }));
      const optionCount = await options.count();

      if (optionCount > 0) {
        // At least one option should have a count displayed
        const firstOption = options.first();
        const optionText = await firstOption.textContent();
        expect(optionText).toMatch(/\(\d+\)/);
      }
    }
  });
});
